function generateReviewSummaryEmail(selectedItems) {
  if (typeof setLoading === "function") setLoading(true, "Drafting Attorney Summary...");
  selectedItems = (Array.isArray(selectedItems) ? selectedItems : []).filter(function (item) {
    return !!item && typeof item === "object";
  });
  var normalizeEmailText = function (value) {
    return String(value || "")
      .replace(/[\r\n\t]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  };
  var actKey = API_KEY || window.API_KEY || localStorage.getItem("eli_gemini_api_key");
  if (!actKey) {
    if (typeof showToast === "function") showToast("⚠️ No API Key found.", "error");
    if (typeof setLoading === "function") setLoading(false);
    return;
  }
  if (!selectedItems.length) {
    if (typeof showToast === "function") showToast("⚠️ Select at least one valid item.");
    if (typeof setLoading === "function") setLoading(false);
    return;
  }
  var rejectedItems = selectedItems.filter(function (item) {
    return String((item && item.actionStatus) || "").toUpperCase() === "REJECTED";
  });
  var revisedItems = selectedItems.filter(function (item) {
    return String((item && item.actionStatus) || "").toUpperCase() === "REVISED";
  });
  var fallbackItems = selectedItems.filter(function (item) {
    return String((item && item.actionStatus) || "").toUpperCase() === "FALLBACK";
  });
  var nonAcceptedItems = selectedItems.filter(function (item) {
    var status = String((item && item.actionStatus) || "").toUpperCase();
    return status === "REJECTED" || status === "REVISED" || status === "FALLBACK";
  });
  var promptLines = nonAcceptedItems.map(function (item) {
    var fromSnippet = normalizeEmailText((item && item.original_snippet) || "");
    var toSnippet = normalizeEmailText((item && item.new_snippet) || "");
    if (fromSnippet.length > 220) fromSnippet = fromSnippet.slice(0, 220) + "...";
    if (toSnippet.length > 220) toSnippet = toSnippet.slice(0, 220) + "...";
    return (
      "Section " +
      item.section +
      ": " +
      item.description +
      "\n" +
      "Action Taken: " +
      item.actionStatus +
      "\n" +
      "Rationale: " +
      (item.rationale || "N/A") +
      "\n" +
      "From Snippet: " +
      (fromSnippet || "N/A") +
      "\n" +
      "To Snippet: " +
      (toSnippet || "N/A")
    );
  });
  var selectedSummary =
    "Counts => Rejected: " +
    String(rejectedItems.length) +
    ", Revised: " +
    String(revisedItems.length) +
    ", Fallback: " +
    String(fallbackItems.length) +
    ". (Accepted changes are not included in this email.)";
  // Inlined emailReviewSummary prompt (was formatPrompt("emailReviewSummary", {selectedSummary, dataIngest})):
  var p = `Draft a formal email to the counterparty regarding our review of the latest draft.

The email should:
1. Open with 'Dear ' (do not include a subject line).
2. Start with a sentence like: 'We have reviewed the latest draft. We accepted many of the proposed changes, but below please find the changes we could not accept or had to revise, along with our reasons.'
3. Only discuss the REJECTED, REVISED, and FALLBACK items listed below. Do NOT mention or list accepted changes.
4. For each item, explain what the proposed change was, what we did (rejected or revised), and provide a concise reason why.
5. Conclude with: 'Please let us know if the revised draft is acceptable.'

${selectedSummary}
Tone: Professional, courteous, firm. This is going to the counterparty, not internal counsel.
CRITICAL RULES: DO NOT include a Subject line. DO NOT mention accepted changes. DO NOT reference 'counterparty' — address them directly. Return ONLY the clean email text without markdown backticks.

DATA INGEST:
${dataIngest}`;
  callGemini(actKey, p)
    .then(function (r) {
      var cleanText = r.replace(/[`]{3}/g, "").trim();
      var overlay = document.createElement("div");
      overlay.style.cssText = "position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(15,23,42,0.85); z-index:10000; display:flex; align-items:center; justify-content:center; backdrop-filter:blur(3px);";
      var modal = document.createElement("div");
      modal.style.cssText = "background:white; width:95%; height:85%; display:flex; flex-direction:column; border-radius:0; box-shadow:0 15px 35px rgba(0,0,0,0.3); resize:both; overflow:hidden; min-width:300px; min-height:400px;";
      var header = document.createElement("div");
      header.style.cssText = "padding:15px; background:#f8fafc; border-bottom:1px solid #e2e8f0; display:flex; justify-content:space-between; align-items:center; cursor:move;";
      header.innerHTML =
        "<div style='font-size:14px; font-weight:900; color:#1e293b; letter-spacing:0.5px;'>📧 EMAIL EDITOR</div>" +
        "<div style='font-size:11px; color:#64748b; font-weight:600;'>Drag corner to resize</div>";
      var txtContainer = document.createElement("div");
      txtContainer.style.cssText = "flex:1; padding:15px; display:flex; flex-direction:column; background:#fff;";
      var txtArea = document.createElement("textarea");
      txtArea.style.cssText = "flex:1; width:100%; height:100%; border:1px solid #cbd5e1; border-radius:0; padding:15px; font-size:13px; color:#334155; font-family:var(--font-sans, sans-serif); line-height:1.6; resize:none; outline:none; box-sizing:border-box;";
      txtArea.value = cleanText;
      txtArea.onfocus = function () {
        this.style.borderColor = "#94a3b8";
        this.style.boxShadow = "0 0 0 3px rgba(148,163,184,0.1)";
      };
      txtArea.onblur = function () {
        this.style.borderColor = "#cbd5e1";
        this.style.boxShadow = "none";
      };
      txtContainer.appendChild(txtArea);
      var footer = document.createElement("div");
      footer.style.cssText = "padding:15px; border-top:1px solid #e2e8f0; background:#f8fafc; display:flex; justify-content:flex-end; gap:10px;";
      var btnClose = document.createElement("button");
      btnClose.innerText = "Cancel";
      btnClose.style.cssText = "padding:10px 20px; background:white; border:1px solid #cbd5e1; border-radius:0; font-weight:700; color:#475569; cursor:pointer;";
      btnClose.onclick = function () {
        document.body.removeChild(overlay);
      };
      var btnCopy = document.createElement("button");
      btnCopy.innerText = "📋 Copy to Clipboard";
      btnCopy.style.cssText = "padding:10px 20px; background:linear-gradient(135deg, #1e3a8a 0%, #1e40af 100%); border:none; border-radius:0; font-weight:700; color:white; cursor:pointer; box-shadow:0 2px 4px rgba(30,58,138,0.2);";
      btnCopy.onclick = function () {
        navigator.clipboard.writeText(txtArea.value);
        this.innerText = "✅ Copied!";
        setTimeout(function () {
          btnCopy.innerText = "📋 Copy to Clipboard";
        }, 2000);
      };
      footer.appendChild(btnClose);
      footer.appendChild(btnCopy);
      modal.appendChild(header);
      modal.appendChild(txtContainer);
      modal.appendChild(footer);
      overlay.appendChild(modal);
      document.body.appendChild(overlay);
    })
    .catch(function (err) {
      if (typeof showToast === "function") showToast("Generation failed.", "error");
    })
    .finally(function () {
      if (typeof setLoading === "function") setLoading(false);
    });
}

