functions.generateInternalConsentEmail:
function generateInternalConsentEmail(recipientName, recipientEmail, selectedItems) {
  var recipientFirst = (recipientName || "").split(/\s+/)[0] || "Colleague";
  if (typeof setLoading === "function") setLoading(true, "Drafting Internal Email to " + recipientFirst + "...");
  selectedItems = (Array.isArray(selectedItems) ? selectedItems : []).filter(function (x) {
    return !!x && typeof x === "object";
  });
  var actKey = API_KEY || window.API_KEY || localStorage.getItem("eli_gemini_api_key");
  if (!actKey) {
    if (typeof showToast === "function") showToast("No API Key found.", "error");
    if (typeof setLoading === "function") setLoading(false);
    return;
  }
  var details = null;
  try {
    details = Office.context.document.settings.get("AgreementDataDetails") || null;
  } catch (e) { }
  var agreementName = details && details.sourceName ? details.sourceName : "this agreement";
  var agreementType = details && details.type ? details.type : "agreement";
  var firstName = window.getEliUserFirstName();
  var normalizeInlineText = function (value) {
    return String(value || "")
      .replace(/[\r\n\t]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  };
  var getFullDocumentTextForInternalEmail = function () {
    return Word.run(async function (context) {
      var bodyHtml = context.document.body.getHtml();
      await context.sync();
      var cleanDoc = getCleanTextAndContext(bodyHtml.value);
      return normalizeInlineText((cleanDoc && cleanDoc.text) || "");
    }).catch(function () {
      return "";
    });
  };
  var toSingleLine = function (s) {
    return String(s || "")
      .replace(/[\r\n]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  };
  var summarizeItemContext = function (x) {
    var oldTxt = toSingleLine(x.original_snippet || "");
    var newTxt = toSingleLine(x.new_snippet || "");
    if (oldTxt.length > 180) oldTxt = oldTxt.substring(0, 180) + "...";
    if (newTxt.length > 180) newTxt = newTxt.substring(0, 180) + "...";
    var oldLabel = oldTxt ? oldTxt : x.new_snippet === "[DELETED]" ? "[DELETED]" : "N/A";
    var newLabel = newTxt ? newTxt : x.original_snippet === "[NEWLY ADDED]" ? "[NEWLY ADDED]" : "N/A";
    var action = String((x && x.actionStatus) || "").toUpperCase();
    return (
      "Section " +
      x.section +
      " — " +
      toSingleLine(x.description || "") +
      " | Action: " +
      action +
      " | From: " +
      oldLabel +
      " | To: " +
      newLabel +
      " | Internal Rationale: " +
      toSingleLine(x.rationale || "N/A") +
      " | Risk Impact: " +
      toSingleLine(x.legal_impact || "N/A")
    );
  };
  var accepted = selectedItems
    .filter(function (x) {
      return x.actionStatus === "ACCEPTED";
    })
    .map(summarizeItemContext);
  var rejected = selectedItems
    .filter(function (x) {
      return x.actionStatus === "REJECTED";
    })
    .map(summarizeItemContext);
  var fallback = selectedItems
    .filter(function (x) {
      return x.actionStatus === "FALLBACK";
    })
    .map(summarizeItemContext);
  var revised = selectedItems
    .filter(function (x) {
      return x.actionStatus === "REVISED";
    })
    .map(summarizeItemContext);
  var dataBlock =
    "Agreement Name: " +
    agreementName +
    "\n" +
    "Agreement Type: " +
    agreementType +
    "\n" +
    "Accepted: " +
    (accepted.length ? accepted.join(" | ") : "None") +
    "\n" +
    "Rejected: " +
    (rejected.length ? rejected.join(" | ") : "None") +
    "\n" +
    "Revised: " +
    (revised.length ? revised.join(" | ") : "None") +
    "\n" +
    "Fallbacks: " +
    (fallback.length ? fallback.join(" | ") : "None") +
    "\n" +
    "Decision Counts: Accepted=" +
    String(accepted.length) +
    ", Rejected=" +
    String(rejected.length) +
    ", Revised=" +
    String(revised.length) +
    ", Fallback=" +
    String(fallback.length);
  getFullDocumentTextForInternalEmail()
    .then(function (docText) {
      if (!normalizeInlineText(docText || "")) {
        return validateApiAndGetText(!1, null);
      }
      return docText;
    })
    .then(function (docText) {
      var excerptForIntel = String(docText || "").substring(0, 9000);
      var intelPrompt = formatPrompt("docIntel", { excerpt: excerptForIntel });
      return callGemini(actKey, intelPrompt).then(function (intelRaw) {
        var intel = tryParseGeminiJSON(intelRaw) || {};
        var parties = toSingleLine(intel.parties || "");
        var overview = toSingleLine(intel.agreementOverview || "");
        var risks = Array.isArray(intel.majorRisks) ? intel.majorRisks : [];
        var cleanRisks = risks
          .map(function (r) {
            return toSingleLine(r || "");
          })
          .filter(function (r) {
            return !!r;
          })
          .slice(0, 6);
        var docIntelBlock =
          "Parties: " +
          (parties || "Not clearly identified in excerpt") +
          "\n" +
          "Agreement Overview: " +
          (overview || "Overview not available from excerpt.") +
          "\n" +
          "Major Risks: " +
          (cleanRisks.length ? cleanRisks.join(" | ") : "No major risks confidently identified from excerpt.");
        // Inlined emailInternalConsent prompt:
          var p = `Write a polished internal consent-request email to ${recipientName} for approval to send a revised draft to external third party.
Must follow this structure exactly with natural polished prose:
Hi ${recipientFirst},
I reviewed and revised [name of agreement] which is a [type of agreement].
Parties: [1 sentence naming parties].
A summary of the agreement is as follows: [1-2 concise sentences].
Major risks to Colgate: [2-4 concise bullets].
Here are the changes I accepted/rejected/revised/fallback.
Use this exact format with numbered bullets and context:
Changes I accepted:
1. ...
2. ...
Changes I rejected:
1. ...
2. ...
Changes I revised:
1. ...
2. ...
Fallbacks I used:
1. ...
2. ...
Each bullet must clearly include ALL of the following: (a) what the change was (b) our decision (accepted/rejected/revised), (c) what changed in from/to terms if available, and (d) how it factually impacts Colgate stated as a matter of fact — do NOT characterize the impact as positive or negative, do NOT say it protects or benefits Colgate. Simply state the concrete obligation or requirement that results (e.g., 'Colgate is now required to provide 30 days notice before termination for convenience' or 'Colgate must indemnify the counterparty for IP claims').
If a category has no items, write 'None.' under that category.
Please confirm consent to send the revised draft to the external party.
Thanks,
${firstName}

Rules: Keep concise, professional, and readable. No markdown. No subject line. Single email body only. Keep bullets short and concrete. Base draft details on the supplied document intelligence and excerpt; do not invent facts not supported by input. CRITICAL: When describing the impact on Colgate, be purely factual and neutral — state the resulting obligation or requirement as a matter of fact. NEVER say the change 'protects', 'benefits', 'strengthens', 'mitigates risk for', or is 'favorable' to Colgate. Just state what Colgate is now required or permitted to do as a result of the decision.

DOCUMENT INTELLIGENCE (from draft text):
${docIntelBlock}

DATA:
${dataBlock}

Agreement Excerpt:
${excerpt}`;
        return callGemini(actKey, p).then(function (emailRaw) {
          return {
            emailRaw: emailRaw,
            parties: parties,
            overview: overview,
            majorRisks: cleanRisks,
          };
        });
      });
    })
    .then(function (result) {
      var body = String((result && result.emailRaw) || "")
        .replace(/```/g, "")
        .trim();
      var partiesLine = toSingleLine((result && result.parties) || "") || "Not clearly identified in excerpt";
      var overviewLine = toSingleLine((result && result.overview) || "") || "Overview not available from excerpt.";
      var risks = result && Array.isArray(result.majorRisks) ? result.majorRisks : [];
      var riskLines = risks
        .map(function (risk) {
          return toSingleLine(risk || "");
        })
        .filter(function (risk) {
          return !!risk;
        })
        .slice(0, 4);
      var topBlock =
        "Parties: " +
        partiesLine +
        "\n" +
        "Agreement Overview: " +
        overviewLine +
        "\n" +
        "Major Risks to Colgate:\n" +
        (riskLines.length
          ? riskLines
            .map(function (risk) {
              return "- " + risk;
            })
            .join("\n")
          : "- No major risks confidently identified from excerpt.") +
        "\n\n";
      var lines = body.split(/\r?\n/);
      var filtered = [];
      var skippingRiskBullets = false;
      lines.forEach(function (line) {
        var trimmed = String(line || "").trim();
        if (/^parties:/i.test(trimmed)) return;
        if (/^agreement overview:/i.test(trimmed)) return;
        if (/^a summary of the agreement is as follows:/i.test(trimmed)) return;
        if (/^total agreement cost:/i.test(trimmed)) return;
        if (/^major risks to colgate:/i.test(trimmed)) {
          skippingRiskBullets = true;
          return;
        }
        if (skippingRiskBullets) {
          if (!trimmed || /^[-*•]\s+/.test(trimmed)) return;
          skippingRiskBullets = false;
        }
        filtered.push(line);
      });
      var greetingRe = new RegExp("^Hi " + recipientFirst + ",\\s*", "i");
      var remainder = filtered.join("\n").replace(greetingRe, "").trim();
      body = "Hi " + recipientFirst + ",\n\n" + topBlock + remainder;
      body = body
        .replace(/[ \t]+\n/g, "\n")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
      var subj = "Consent Request: Revised Draft for External Send";
      var gmailUrl =
        "https://mail.google.com/mail/?view=cm&fs=1" +
        "&to=" +
        encodeURIComponent(recipientEmail || "") +
        "&su=" +
        encodeURIComponent(subj) +
        "&body=" +
        encodeURIComponent(body);
      if (Office.context.ui && Office.context.ui.openBrowserWindow) {
        Office.context.ui.openBrowserWindow(gmailUrl);
      } else {
        window.open(gmailUrl, "_blank");
      }
      if (typeof showToast === "function") showToast("Opening Gmail draft to " + recipientFirst + "...");
    })
    .catch(function (err) {
      if (typeof showToast === "function") showToast("Internal email draft generation failed.", "error");
    })
    .finally(function () {
      if (typeof setLoading === "function") setLoading(false);
    });
}

functions.generateColleagueFlaggedEmail:
function generateColleagueFlaggedEmail(recipientName, colleagueCtx) {
  if (typeof setLoading === "function") setLoading(true, "Drafting Colleague Email...");
  var actKey = API_KEY || window.API_KEY || localStorage.getItem("eli_gemini_api_key");
  if (!actKey) {
    if (typeof showToast === "function") showToast("No API Key found.", "error");
    if (typeof setLoading === "function") setLoading(false);
    return;
  }
  var firstName = window.getEliUserFirstName();
  var agreementName = colleagueCtx.agreementName || "this agreement";
  var agreementType = colleagueCtx.agreementType || "agreement";
  var flaggedSections = colleagueCtx.flaggedSections || [];
  var getDocExcerpt = function () {
    return Word.run(async function (context) {
      var bodyHtml = context.document.body.getHtml();
      await context.sync();
      var cleanDoc = getCleanTextAndContext(bodyHtml.value);
      return String((cleanDoc && cleanDoc.text) || "").substring(0, 6000);
    }).catch(function () {
      return "";
    });
  };
  getDocExcerpt()
    .then(function (excerpt) {
      var sectionDetails = colleagueCtx.flaggedSectionDetails || [];
      var flaggedList;
      if (sectionDetails.length > 0) {
        flaggedList = sectionDetails
          .map(function (d, i) {
            var header =
              String(i + 1) + ". " + (d.articleName && d.articleName !== d.name ? d.articleName + " — " : "") + d.name;
            if (d.fullText) {
              header += "\n   Section Text:\n   " + d.fullText.substring(0, 2000).replace(/\n/g, "\n   ");
            }
            return header;
          })
          .join("\n\n");
      } else {
        flaggedList = flaggedSections
          .map(function (s, i) {
            return String(i + 1) + ". " + s;
          })
          .join("\n");
      }
      // Inlined emailColleagueFlagged prompt:
      var prompt = `Write a polished, concise internal email from ${firstName} to ${recipientName} (a colleague) asking for their input on specific sections of a contract.
Agreement Name: ${agreementName}
Agreement Type: ${agreementType}
The email should follow this exact structure:
1. Start with 'Hi ${recipientFirst},'
2. First paragraph: Briefly state you are reviewing ${agreementName} which is a ${agreementType}. Provide a 2-3 sentence summary of what the ENTIRE agreement covers (not just the flagged sections). Use the excerpt below to understand the full scope.
3. After the summary paragraph, write a transition sentence like: 'I would like to discuss certain sections of this agreement with you. A summary of the sections and their text are below:'
4. For each flagged section:
   a. Start with 'I would like to discuss [SECTION NAME] with you.'
   b. Then write a brief AI summary of what that section covers (1-2 sentences, declarative — start with 'This section...').
   c. Then on a new line, include the full clean section text exactly as provided (under a label like 'Section Text:').
5. After listing all sections, close with a single sentence asking if they could review these sections and share their thoughts.
6. Sign off with 'Thanks,
${firstName}'

Flagged sections:
${flaggedList}

Rules:
- The first paragraph MUST summarize the entire agreement, not just the flagged sections.
